typedef long long ll;

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *A = (ll*)malloc(sizeof(ll) * N);
    ll *B = (ll*)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &A[i]);
    for (int i = 0; i < N; i++) scanf("%lld", &B[i]);

    if (N == 1) {
        if (A[0] == B[0]) printf("0\n");
        else printf("-1\n");
        free(A); free(B);
        return 0;
    }

    if (N == 2) {
        if (A[0] == B[0] && A[1] == B[1]) printf("0\n");
        else printf("-1\n");
        free(A); free(B);
        return 0;
    }

    ll *cnt = (ll*)malloc(sizeof(ll) * N);
    ll ans = 0;

    for (int i = 0; i < N; i++) {
        int l = (i - 1 + N) % N;
        int r = (i + 1) % N;
        ll s = B[l] + B[r];

        if (s == 0) {
            if (A[i] != B[i]) {
                printf("-1\n");
                free(A); free(B); free(cnt);
                return 0;
            }
            cnt[i] = 0;
            continue;
        }

        ll diff = A[i] - B[i];
        if (diff < 0 || diff % s != 0) {
            printf("-1\n");
            free(A); free(B); free(cnt);
            return 0;
        }
        cnt[i] = diff / s;
        ans += cnt[i];
    }

    for (int i = 0; i < N; i++) {
        int l = (i - 1 + N) % N;
        int r = (i + 1) % N;
        ll finalv = A[i] - cnt[i] * (B[l] + B[r]) + cnt[l] * B[i] + cnt[r] * B[i];
        if (finalv != B[i]) {
            printf("-1\n");
            free(A); free(B); free(cnt);
            return 0;
        }
    }

    printf("%lld\n", ans);

    free(A);
    free(B);
    free(cnt);
    return 0;
}

