    for(auto&x:B)cin>>x;
    // greedy reverse on B
    priority_queue<pair<ll,int>> pq;
    for(int i=0;i<n;i++) pq.push({B[i],i});
    ll ops=0;
    while(true){
        if(B==A){cout<<ops;return 0;}
        auto [val,i]=pq.top(); pq.pop();
