#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int64> A(N), B(N);
    for (int i = 0; i < N; i++) cin >> A[i];
    for (int i = 0; i < N; i++) cin >> B[i];

    // Special case N=2:
    // Replacing one element sets it equal to the other element.
    // Thus each value can only become one of the initial two values,
    // and after one operation both become equal.
    if (N == 2) {
        // 0 operations
        if (A == B) {
            cout << 0 << '\n';
            return 0;
        }
        // 1 operation possibilities
        if ((B[0] == A[1] && B[1] == A[1]) || (B[0] == A[0] && B[1] == A[0])) {
            cout << 1 << '\n';
            return 0;
        }
        cout << -1 << '\n';
        return 0;
    }

    // For N >= 3:
    // Reverse process:
    // If current B[i] >= B[i-1] + B[i+1], then the last forward operation on i
    // could have increased A[i] by multiples of (neighbors sum), so in reverse
    // we can subtract neighbors sum from B[i].
    //
    // Greedy with priority queue on indices where reduction is possible.
    vector<int64> cur = B;
    priority_queue<pair<int64,int>> pq;
    for (int i = 0; i < N; i++) pq.push({cur[i], i});

    long long ans = 0;

    auto left = [&](int i){ return (i - 1 + N) % N; };
    auto right = [&](int i){ return (i + 1) % N; };

    while (!pq.empty()) {
        auto [val, i] = pq.top();
        pq.pop();
        if (cur[i] != val) continue;

        int l = left(i), r = right(i);
        int64 s = cur[l] + cur[r];

        if (cur[i] <= A[i]) continue;
        if (s <= 0) { // impossible here since all positive, but keep safe
            cout << -1 << '\n';
            return 0;
        }
        if (cur[i] < s) continue;

        // Need cur[i] to stay >= A[i].
        // We can subtract s multiple times.
        long long k = (cur[i] - A[i]) / s;
        if (k == 0) continue;

        cur[i] -= s * k;
        ans += k;

        pq.push({cur[i], i});
        pq.push({cur[l], l});
        pq.push({cur[r], r});
    }

    if (cur == A) cout << ans << '\n';
    else cout << -1 << '\n';

    return 0;
}

