public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        long[] A = new long[N];
        long[] B = new long[N];
        for (int i = 0; i < N; i++) A[i] = sc.nextLong();
        for (int i = 0; i < N; i++) B[i] = sc.nextLong();

        if (N == 3) {
            System.out.println(solve3(A, B));
            return;
        }

        // For even N, check alternating sum invariant
        long sumA = 0, sumB = 0;
        for (int i = 0; i < N; i++) {
            if (i % 2 == 0) {
                sumA += A[i];
                sumB += B[i];
            } else {
                sumA -= A[i];
                sumB -= B[i];
            }
        }
        if (sumA != sumB) {
            System.out.println(-1);
            return;
        }

        long ops = 0;
        long[] cur = A.clone();
        // We can make all values match by propagating differences
        for (int i = 0; i < N; i++) {
            if (cur[i] == B[i]) continue;
            long diff = B[i] - cur[i];
            // To change cur[i] by diff, we need to apply operation on neighbors
            // Actually operation on i changes cur[i] to cur[i-1]+cur[i+1]
            // We can instead adjust by operating on i+1 or i-1
            // Greedy: work from left to right for even N
            int next = (i + 1) % N;
            int prev = (i - 1 + N) % N;
            if (i % 2 == 0) {
                // change via next neighbor
                long steps = diff;
                ops += Math.abs(steps);
                cur[i] += steps;
                cur[next] += steps;
                cur[prev] += steps;
            } else {
                long steps = diff;
                ops += Math.abs(steps);
                cur[i] += steps;
                cur[next] += steps;
                cur[prev] += steps;
            }
        }

        // Verify
        for (int i = 0; i < N; i++) {
            if (cur[i] != B[i]) {
                System.out.println(-1);
                return;
            }
        }
        System.out.println(ops);
    }

    static long solve3(long[] A, long[] B) {
        // For N=3, we can solve explicitly using reverse operations
        // The operation is reversible; we can simulate backwards from B to A
        long[] a = A.clone();
        long[] b = B.clone();
        long ops = 0;
        // Try to match by working on one variable at a time
        // Since N=3, we can only change one number at a time
        // Strategy: make a[0]==b[0] by adjusting a[1] and a[2]?
        // Actually operation on i: a[i] = a[i-1]+a[i+1]
        // So if we set a[0] = a[2] + a[1], we change a[0] only.
        // Reverse: from b, we can set b[1] = b[0] - b[2] etc.
        // We'll just BFS limited depth? No, use math.

        // For N=3, operation at i sets a[i] to sum of other two.
        // So each operation changes only one element.
        // We can compute needed changes directly.
        // Try all permutations of operation order? N small, but values up to 1e9.
        // Use reverse: while b != a, try to reduce largest difference.

        // Simpler: since only one element changes per op, we can match one by one.
        for (int iter = 0; iter < 1000000; iter++) {
            if (Arrays.equals(a, b)) return ops;
            // Find index where difference is largest in absolute value
            int idx = -1;
            long maxDiff = 0;
            for (int i = 0; i < 3; i++) {
                long diff = Math.abs(b[i] - a[i]);
                if (diff > maxDiff) {
                    maxDiff = diff;
                    idx = i;
                }
            }
            if (maxDiff == 0) break;
            // We want a[idx] to become b[idx]
            // a[idx] = a[(idx+1)%3] + a[(idx+2)%3]
            long target = b[idx];
            long sumNeighbors = a[(idx+1)%3] + a[(idx+2)%3];
            if (sumNeighbors == target) {
                a[idx] = target;
                ops++;
                continue;
            }
            // Reverse: we can change a neighbor so that sum becomes target
            // Let n1 = (idx+1)%3, n2 = (idx+2)%3
            // We can apply operation on n1: a[n1] = a[(n1+1)%3] + a[(n1+2)%3]
            // That changes a[n1] to sum of other two
            // To make a[idx] = target, we need a[n1] = target - a[n2]
            // So we can set a[n1] to that value by operating on n2? This gets messy.
            // Instead, use simple approach: if we can't directly match, try to reduce differences
            boolean madeChange = false;
            for (int i = 0; i < 3; i++) {
                int n1 = (i+1)%3, n2 = (i+2)%3;
                long newVal = a[n1] + a[n2];
                if (Math.abs(newVal - b[i]) < Math.abs(a[i] - b[i])) {
                    a[i] = newVal;
                    ops++;
                    madeChange = true;
                    break;
                }
            }
            if (!madeChange) break;
        }
        if (Arrays.equals(a, b)) return ops;
        return -1;
    }
}

