public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        long[] A = new long[N];
        long[] B = new long[N];
        for (int i = 0; i < N; i++) A[i] = fs.nextLong();
        for (int i = 0; i < N; i++) B[i] = fs.nextLong();

        if (N == 1) {
            System.out.println(A[0] == B[0] ? 0 : -1);
            return;
        }

        // For N=2, each operation keeps the chosen value unchanged
        // because both neighbors are the other element, so replacing Ai by Aj+Aj?
        // Actually in a 2-cycle, both neighbors of i are the same other index.
        // But the original problem constraints in the known task effectively use N>=3.
        // Handle directly by simulation of invariance:
        if (N == 2) {
            System.out.println((A[0] == B[0] && A[1] == B[1]) ? 0 : -1);
            return;
        }

        long[] cur = B.clone();
        ArrayDeque<Integer> q = new ArrayDeque<>();
        boolean[] inq = new boolean[N];

        for (int i = 0; i < N; i++) {
            if (cur[i] > A[i]) {
                q.add(i);
                inq[i] = true;
            }
        }

        long ans = 0;

        while (!q.isEmpty()) {
            int i = q.poll();
            inq[i] = false;

            long s = cur[(i - 1 + N) % N] + cur[(i + 1) % N];
            if (s <= 0) continue;

            if (cur[i] <= A[i]) continue;

            long maxK = (cur[i] - A[i]) / s;
            if (maxK <= 0) continue;

            cur[i] -= maxK * s;
            ans += maxK;

            // If still above A[i], it may need more after neighbors change.
            if (cur[i] > A[i] && !inq[i]) {
                q.add(i);
                inq[i] = true;
            }

            int l = (i - 1 + N) % N;
            int r = (i + 1) % N;
            if (cur[l] > A[l] && !inq[l]) {
                q.add(l);
                inq[l] = true;
            }
            if (cur[r] > A[r] && !inq[r]) {
                q.add(r);
                inq[r] = true;
            }
        }

        for (int i = 0; i < N; i++) {
            if (cur[i] != A[i]) {
                System.out.println(-1);
                return;
            }
        }
        System.out.println(ans);
    }
}
